package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.signal.WritableSignal;

import static com.pathland.view.signal.Signals.computed;

/**
 * The music player's custom {@link AudioStyle}: the transport controls
 * (prev / play-pause / next), a seek slider with elapsed/duration labels, and a
 * volume slider — all bound to the media configuration's signals. This becomes
 * the {@code AUDIO} node's children, so the renderer emits a hidden media
 * element alongside these app-defined controls (real playback, app-driven).
 */
public final class PlayerControlsStyle implements AudioStyle {

    private final WritableSignal<Integer> trackIndex;

    private PlayerControlsStyle(WritableSignal<Integer> trackIndex) {
        this.trackIndex = trackIndex;
    }

    /** A player-controls style over {@code trackIndex} (drives prev/next + the duration label). */
    public static PlayerControlsStyle of(WritableSignal<Integer> trackIndex) {
        return new PlayerControlsStyle(trackIndex);
    }

    @Override
    public View makeBody(Configuration config) {
        var current = computed(() -> MusicPlayerView.at(trackIndex.get()));
        var elapsed = computed(() -> MusicPlayerView.fmt(config.position().get()));
        var glyph = computed(() -> config.playing().get() ? "⏸" : "▶");
        return HStack.of(Alignment.CENTER, 14f,
                Button.of("⏮", this::prev).with(FontSize.of(20)),
                Button.of(Text.of(glyph), () -> config.playing().update(v -> !v)).with(FontSize.of(28)),
                Button.of("⏭", this::next).with(FontSize.of(20)),
                Text.of(elapsed).with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG)),
                Slider.of(config.position(), 0f, MusicPlayerView.SEEK_MAX).with(FrameMod.of(240f)),
                Text.of(computed(() -> MusicPlayerView.fmt(current.get().duration())))
                        .with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG)),
                Spacer.of(),
                Text.of("🔊").with(FontSize.of(16)),
                Slider.of(config.volume(), 0f, 1f).with(FrameMod.of(96f))
        ).with(Padding.of(12, 16, 12, 16));
    }

    /** Previous track (wraps around); the seek restarts via the position binding. */
    private void prev() {
        trackIndex.update(i -> (i - 1 + MusicPlayerView.TRACKS.size()) % MusicPlayerView.TRACKS.size());
    }

    /** Next track (wraps around); the seek restarts via the position binding. */
    private void next() {
        trackIndex.update(i -> (i + 1) % MusicPlayerView.TRACKS.size());
    }
}

package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.signal.WritableSignal;

import static com.pathland.view.signal.Signals.computed;

/**
 * The bottom player bar: the now-playing title/artist and an app-driven
 * {@link Audio} node whose custom {@link PlayerControlsStyle} provides the real
 * transport controls (prev / play-pause / next, seek, volume). The audio element
 * is hidden; the controls drive it through the bound media state, and playback
 * events (time/ended/volume) flow back into the same state.
 */
public final class PlayerBar implements View {

    private final WritableSignal<Integer> trackIndex;
    private final WritableSignal<Float> position;
    private final WritableSignal<Boolean> playing;
    private final WritableSignal<Float> volume;

    /**
     * @param trackIndex the current track index (drives the source + title/artist)
     * @param position   the play position (seconds), bound to the seek slider
     * @param playing    toggled by the play/pause button
     * @param volume     bound to the volume slider (0..1)
     */
    public PlayerBar(WritableSignal<Integer> trackIndex, WritableSignal<Float> position,
                     WritableSignal<Boolean> playing, WritableSignal<Float> volume) {
        this.trackIndex = trackIndex;
        this.position = position;
        this.playing = playing;
        this.volume = volume;
    }

    @Override
    public View body() {
        var current = computed(() -> MusicPlayerView.at(trackIndex.get()));
        return HStack.of(Alignment.CENTER, 14f,
                VStack.of(Alignment.LEADING, 2,
                        Text.of(computed(() -> current.get().title()))
                                .with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                        Text.of(computed(() -> current.get().artist()))
                                .with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG))
                ).with(Padding.of(8, 20, 8, 20)).with(FrameMod.of(180f)),
                Spacer.of(),
                // The real audio: a hidden media element driven by the custom
                // PlayerControlsStyle (transport + seek + volume).
                Audio.of(computed(() -> current.get().audio()))
                        .playing(playing)
                        .position(position)
                        .volume(volume)
                        .duration(MusicPlayerView.SEEK_MAX)
                        .onEnded(this::ended)
                        .with(AudioStyleMod.of(PlayerControlsStyle.of(trackIndex)))
        )
        .with(Padding.of(12, 16, 12, 16))
        .with(Background.of(MusicPlayerView.BAR_BG))
        .with(Border.of(MusicPlayerView.BAR_BORDER, 1f, 0f))
        .with(FrameMod.of(Commands.Size.FILL, MusicPlayerView.BAR_HEIGHT));
    }

    /** The media ended: advance to the next track and restart playback. */
    private void ended() {
        trackIndex.update(i -> (i + 1) % MusicPlayerView.TRACKS.size());
        position.set(0f);
