package com.pathland.demo.spring;

import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.core.io.support.PathMatchingResourcePatternResolver;
import org.springframework.util.DigestUtils;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Serves the demo's media assets ({@code /_pathland/**}) from a real filesystem
 * directory instead of inside the jar, so Spring's static handler answers
 * byte-range requests with {@code 206 Partial Content} + {@code Content-Range}.
 *
 * <p>An {@code <audio>} element seeking beyond its buffer issues a {@code Range}
 * request; the jar's classpath static handler replies with the full {@code 200}
 * (no {@code Accept-Ranges}), which makes browsers treat the response as a fresh
 * resource and restart the media at byte 0 — a seek "restarts the track".
 * Serving real files restores native range support. Assets are extracted once
 * per asset set (a manifest guard skips the copy on later starts).
 */
@Configuration
public class MediaRangeConfig implements WebMvcConfigurer {

    private static final Path MEDIA_DIR = Paths.get(
            System.getProperty("java.io.tmpdir"), "pathland-media");

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        extractMedia();
        registry.addResourceHandler("/_pathland/**")
                .addResourceLocations(MEDIA_DIR.toUri().toString());
    }

    private static void extractMedia() {
        try {
            List<Resource> resources = sortedMediaResources();
            String manifest = manifestOf(resources);
            Path manifestFile = MEDIA_DIR.resolve("manifest.txt");
            if (Files.isRegularFile(manifestFile) && manifest.equals(Files.readString(manifestFile))) {
                return; // already extracted for this asset set
            }
            deleteRecursively(MEDIA_DIR);
            Files.createDirectories(MEDIA_DIR);
            for (Resource resource : resources) {
                String rel = relativeToPathland(resource);
                if (rel == null) {
                    continue;
                }
                Path target = MEDIA_DIR.resolve(rel);
                Files.createDirectories(target.getParent());
                try (InputStream in = resource.getInputStream()) {
                    Files.copy(in, target, StandardCopyOption.REPLACE_EXISTING);
                }
            }
            Files.writeString(manifestFile, manifest);
        } catch (IOException e) {
            throw new UncheckedIOException("could not extract /_pathland media assets", e);
        }
    }

    /** The demo's media assets, in stable order (sorted by path). */
    private static List<Resource> sortedMediaResources() throws IOException {
        PathMatchingResourcePatternResolver resolver = new PathMatchingResourcePatternResolver();
        Resource[] resources = resolver.getResources("classpath*:/static/_pathland/**");
        List<Resource> list = new ArrayList<>(List.of(resources));
        list.sort(Comparator.comparing(MediaRangeConfig::urlOf));
        return list;
    }

    /** A content manifest: one {@code path<TAB>md5} line per asset. */
    private static String manifestOf(List<Resource> resources) throws IOException {
        StringBuilder sb = new StringBuilder();
        for (Resource resource : resources) {
            String rel = relativeToPathland(resource);
            if (rel == null) {
                continue;
            }
            try (InputStream in = resource.getInputStream()) {
                sb.append(rel).append('\t').append(DigestUtils.md5DigestAsHex(in)).append('\n');
            }
        }
        return sb.toString();
    }

    /** The asset's path below {@code _pathland/} (from its URL), or {@code null}. */
    private static String relativeToPathland(Resource resource) {
        String url = urlOf(resource);
        int idx = url.lastIndexOf("/static/_pathland/");
        if (idx < 0) {
            return null;
        }
        return url.substring(idx + "/static/_pathland/".length());
    }

    private static String urlOf(Resource resource) {
        try {
            return resource.getURL().toString();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static void deleteRecursively(Path dir) throws IOException {
        if (!Files.exists(dir)) {
            return;
        }
        try (var walk = Files.walk(dir)) {
            for (Path p : walk.sorted(Comparator.reverseOrder()).toList()) {
                Files.deleteIfExists(p);
            }
        }
    }
}

