import com.pathland.demo.DemoTheme;
import com.pathland.demo.music.MusicPlayerView;
import com.pathland.view.Environment;
import com.pathland.view.emit.Emitter;
import com.pathland.view.emit.InputDispatcher;
import com.pathland.view.emit.RenderResult;
import com.pathland.view.ffm.PathlandCore;
import com.pathland.view.ffm.RingOpcodeSink;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;
import com.pathland.view.state.InMemoryStateStore;
import com.pathland.view.state.PersistentState;
import com.sun.jna.Memory;
import com.sun.jna.Pointer;

public class SeedPlaying {
    public static void main(String[] args) throws Exception {
        PathlandCore core = PathlandCore.instance();
        try (RingOpcodeSink sink = new RingOpcodeSink(core)) {
            Pointer handle = sink.handle();
            InMemoryStateStore store = new InMemoryStateStore();
            store.save("player.playing:desktop", Boolean.TRUE);
            store.save("player.position:desktop", 12.0f);
            PersistentState state = new PersistentState(store, "desktop");
            WritableSignal<String> activePath = Signals.signal("/");
            Emitter emitter = new Emitter(sink, DemoTheme.adaptive());
            RenderResult result = emitter.mount(new MusicPlayerView(), new Environment(state));
            InputDispatcher dispatcher = new InputDispatcher(result, activePath);
            com.pathland.demo.gtk.RingEventReader reader =
                    new com.pathland.demo.gtk.RingEventReader(core.ringPtr(handle), core.ringLen(handle));
            var renderer = com.pathland.demo.gtk.GtkRendererNative.instance();
            renderer.setAssetRoot(java.nio.file.Paths.get(System.getProperty("java.io.tmpdir"), "pathland-gtk-assets").toString());
            com.pathland.demo.gtk.GtkRendererNative.EventCallback onEvent = () -> {
                Memory buf = new Memory(64L * 16);
                int n = core.drainEvents(handle, buf, 64);
                if (n > 0) {
                    dispatcher.dispatch(reader.decode(buf.getByteArray(0, n * 16)));
                }
            };
            renderer.runRing(core.ringMut(handle), onEvent, 900, 700);
        }
    }
}

