/// Composite Override Mode: attach a control's custom child tree as a box
    /// wrapped by the control's native shell (the widget itself).
    ///
    /// Composite bodies attach to button-like controls (`GtkButton` and
    /// subclasses — `ToggleButton`, `CheckButton`, `MenuButton`); other controls
    /// ignore children.
    ///
    /// The body box's orientation follows the HTML renderer's composite layout:
    /// a `BUTTON` body is a **horizontal row** (`.pathland-button` is
    /// `display:inline-flex; align-items:center`), while `TOGGLE`/`MENU` bodies
    /// stay **vertical** (HTML wraps those as block/inline-block).
    fn sync_composite_children(&mut self, parent_id: u32, children: &[u32]) {
        let Some(parent) = self.widgets.get(&parent_id).cloned() else {
            return;
        };
        let Ok(btn) = parent.downcast::<gtk::Button>() else {
            return;
        };
        let horizontal = self
            .tree
            .node(parent_id)
            .is_some_and(|n| composite_horizontal(n.component_type));
        // A composite control sizes to its content on the main axis unless the
        // node explicitly fills it. Without this, the enclosing box's default
        // `valign`/`halign` of `Fill` stretches the control to the available
        // space (e.g. a library row) — inflating content like fixed-size images.
        let fills_height = self
            .tree
            .node(parent_id)
            .is_some_and(|n| matches!(size_hint(n.properties.get(&property_id::HEIGHT).copied()), SizeHint::Fill));
        let fills_width = self
            .tree
            .node(parent_id)
            .is_some_and(|n| matches!(size_hint(n.properties.get(&property_id::WIDTH).copied()), SizeHint::Fill));
        if !fills_height {
            btn.set_valign(Align::Center);
        }
        if !fills_width {
            btn.set_halign(Align::Center);
        }
        let box_widget: gtk::Widget = if let Some(bx) = self.composite_boxes.get(&parent_id).cloned() {
            bx
        } else {
            let bx = GtkBox::new(
                if horizontal {
                    gtk::Orientation::Horizontal
                } else {
                    gtk::Orientation::Vertical
                },
                0,
            );
            btn.set_child(Some(&bx));
            let bxw: gtk::Widget = bx.upcast();
            self.composite_boxes.insert(parent_id, bxw.clone());
            bxw
        };

