            let Some(cn) = self.tree.node(*child_id) else {
                continue;
            };
            let main = layout::main_axis_align(cn, l.orientation);
            let cross = layout::cross_axis_align(cn, l.orientation, stack_align);
            if layout::cross_axis_is_horizontal(l.orientation) {
                w.set_halign(cross);
                w.set_valign(main);
